javascript: (function () {
  function e(e) {
    const t = { fields: [] },
      n = e.elements;
    for (let e = 0; e < n.length; e++) {
      const o = n[e];
      ('INPUT' !== o.tagName &&
        'SELECT' !== o.tagName &&
        'TEXTAREA' !== o.tagName) ||
        t.fields.push({
          name: o.name,
          type: o.type,
          tagName: o.tagName,
          id: o.id,
          placeholder: o.placeholder,
        });
    }
    return t;
  }
  function t() {
    const e = document.createElement('div');
    return (
      (e.style.cssText =
        "\n            position: fixed;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            background-color: rgba(0, 128, 255, 0.3); /* Semi-transparent blue */\n            z-index: 10000; /* Ensure it's on top */\n            pointer-events: none; /* Allows clicks to pass through */\n            border: 2px dashed blue; /* Visual indication of selection area */\n        "),
      (e.id = 'form-autofill-overlay'),
      document.body.appendChild(e),
      e
    );
  }
  function n() {
    const e = document.getElementById('form-autofill-overlay');
    e && e.remove();
  }
  async function o(t, n) {
    const o = prompt('Please enter your OpenAI API key:');
    if (!o)
      return void alert('OpenAI API key is required to use this bookmarklet.');
    const r = `\n            You are a form-filling assistant.  Given the following HTML form structure,\n            generate realistic, plausible sample data to fill the form.  Return the data\n            as a JSON object where the keys are the form field names.  Do not include\n            any explanation or preamble before the JSON.  The JSON should have a flat\n            structure (no nested objects unless the form field itself implies a hierarchy).\n            Ensure that the data types in the JSON match the input types\n            (e.g., numbers for number fields, dates for date fields, etc.).\n            Be creative and generate diverse, realistic-looking data.  If a field\n            name suggests personal information, generate plausible examples of that\n            information.  If a field is a select dropdown, choose one of the options.\n            If you don't know what to put, use a safe default value of "test".\n\n            Form Structure:\n            ${JSON.stringify(
      e(t),
      null,
      2
    )}\n        `;
    try {
      const e = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${o}`,
        },
        body: JSON.stringify({
          model: 'gpt-4o-mini',
          messages: [{ role: 'user', content: r }],
          response_format: { type: 'json_object' },
        }),
      });
      if (!e.ok) {
        const t = await e.json();
        return (
          console.error('OpenAI API Error:', t),
          void alert(
            `Error: ${e.status} - ${
              t.error?.message ||
              'Failed to communicate with OpenAI.  Check console for details.'
            }`
          )
        );
      }
      const t = await e.json(),
        s = t.choices?.[0]?.message?.content;
      if (!s)
        return void alert(
          'Error: No completion was returned from the OpenAI API.'
        );
      let l;
      try {
        l = JSON.parse(s);
      } catch (e) {
        return (
          console.error('Error parsing JSON response:', s),
          void alert(
            'Error: Could not parse the JSON response from OpenAI.  The response was: ' +
              s
          )
        );
      }
      a(n, l);
    } catch (e) {
      console.error('Error:', e), alert('An error occurred: ' + e.message);
    }
  }
  function a(e, t) {
    for (const n in t)
      if (t.hasOwnProperty(n)) {
        const o = e.elements[n];
        if (o) {
          const a = t[n];
          if ('select-one' === o.type) {
            for (let e = 0; e < o.options.length; e++)
              if (o.options[e].value === a || o.options[e].text === a) {
                o.selectedIndex = e;
                break;
              }
          } else if ('radio' === o.type) {
            const t = e.querySelectorAll(`input[name="${n}"]`);
            if (t.length)
              for (let e = 0; e < t.length; e++)
                if (t[e].value === a) {
                  t[e].checked = !0;
                  break;
                }
          } else
            'checkbox' === o.type
              ? !0 === a || 'true' === a || 1 === a
                ? (o.checked = !0)
                : (o.checked = !1)
              : (o.value = a);
          o.dispatchEvent(new Event('input', { bubbles: !0 })),
            o.dispatchEvent(new Event('change', { bubbles: !0 }));
        }
      }
    alert('Form filled with sample data!');
  }
  let r = null,
    s = null;
  function l(e) {
    const a = e.target;
    if (r)
      return (
        n(),
        document.removeEventListener('click', l, !0),
        o(r, r),
        void (r = null)
      );
    const i = a.closest('form');
    i &&
      (e.preventDefault(),
      (r = i),
      (s = t()),
      (i.style.border = '2px solid blue'),
      (i.style.boxShadow = '0 0 5px blue'),
      (s.textContent = 'Click again on this form to autofill it...'),
      (s.style.display = 'flex'),
      (s.style.alignItems = 'center'),
      (s.style.justifyContent = 'center'),
      (s.style.color = 'blue'),
      (s.style.fontWeight = 'bold'),
      (s.style.fontFamily = 'sans-serif'),
      document.addEventListener('click', l, !0));
  }
  document.addEventListener('click', l, !0);
})();
